export const InlineQueryResultsButton = Schema.Struct({ "text": Schema.String.annotate({ "description": "Label text on the button" }), "web_app": Schema.optionalKey(Schema.suspend((): Schema.Codec<WebAppInfo> => WebAppInfo).annotate({ "description": "*Optional*. Description of the [Web App](https://core.telegram.org/bots/webapps) that will be launched when the user presses the button. The Web App will be able to switch back to the inline mode using the method [switchInlineQuery](https://core.telegram.org/bots/webapps#initializing-mini-apps) inside the Web App." })), "start_parameter": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. [Deep-linking](https://core.telegram.org/bots/features#deep-linking) parameter for the /start message sent to the bot when a user presses the button. 1-64 characters, only `A-Z`, `a-z`, `0-9`, `_` and `-` are allowed.  \n  \n*Example:* An inline bot that sends YouTube videos can ask the user to connect the bot to their YouTube account to adapt search results accordingly. To do this, it displays a 'Connect your YouTube account' button above the results, or even before showing any. The user presses the button, switches to a private chat with the bot and, in doing so, passes a start parameter that instructs the bot to return an OAuth link. Once done, the bot can offer a [*switch\\_inline*](https://core.telegram.org/bots/api#inlinekeyboardmarkup) button so that the user can easily return to the chat where they wanted to use the bot's inline capabilities." }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(Schema.isMaxCodePoints(64).annotate({ "expected": "a string with at most 64 code points" }))) }).annotate({ "description": "This object represents a button to be shown above inline query results. You **must** use exactly one of the optional fields.", "identifier": "InlineQueryResultsButton" })
export type MenuButtonWebApp = { readonly "type": "web_app", readonly "text": string, readonly "web_app": WebAppInfo }
export const MenuButtonWebApp = Schema.Struct({ "type": Schema.Literal("web_app").annotate({ "description": "Type of the button, must be *web\\_app*" }), "text": Schema.String.annotate({ "description": "Text on the button" }), "web_app": Schema.suspend((): Schema.Codec<WebAppInfo> => WebAppInfo).annotate({ "description": "Description of the Web App that will be launched when the user presses the button. The Web App will be able to send an arbitrary message on behalf of the user using the method [answerWebAppQuery](https://core.telegram.org/bots/api#answerwebappquery). Alternatively, a `t.me` link to a Web App of the bot can be specified in the object instead of the Web App's URL, in which case the Web App will be opened as if the user pressed the link." }) }).annotate({ "description": "Represents a menu button, which launches a [Web App](https://core.telegram.org/bots/webapps).", "identifier": "MenuButtonWebApp" })
export type InlineKeyboardButton = { readonly "text": string, readonly "icon_custom_emoji_id"?: string, readonly "style"?: "danger" | "success" | "primary", readonly "url"?: string, readonly "callback_data"?: string, readonly "web_app"?: WebAppInfo, readonly "login_url"?: LoginUrl, readonly "switch_inline_query"?: string, readonly "switch_inline_query_current_chat"?: string, readonly "switch_inline_query_chosen_chat"?: SwitchInlineQueryChosenChat, readonly "copy_text"?: CopyTextButton, readonly "callback_game"?: CallbackGame, readonly "pay"?: boolean }
export const InlineKeyboardButton = Schema.Struct({ "text": Schema.String.annotate({ "description": "Label text on the button" }), "icon_custom_emoji_id": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Unique identifier of the custom emoji shown before the text of the button. Can only be used by bots that purchased additional usernames on [Fragment](https://fragment.com) or in the messages directly sent by the bot to private, group and supergroup chats if the owner of the bot has a Telegram Premium subscription." })), "style": Schema.optionalKey(Schema.Literals(["danger", "success", "primary"]).annotate({ "description": "*Optional*. Style of the button. Must be one of “danger” (red), “success” (green) or “primary” (blue). If omitted, then an app-specific style is used." })), "url": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. HTTP or tg:// URL to be opened when the button is pressed. Links `tg://user?id=<user_id>` can be used to mention a user by their identifier without using a username, if this is allowed by their privacy settings." })), "callback_data": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Data to be sent in a [callback query](https://core.telegram.org/bots/api#callbackquery) to the bot when the button is pressed, 1-64 bytes" })), "web_app": Schema.optionalKey(Schema.suspend((): Schema.Codec<WebAppInfo> => WebAppInfo).annotate({ "description": "*Optional*. Description of the [Web App](https://core.telegram.org/bots/webapps) that will be launched when the user presses the button. The Web App will be able to send an arbitrary message on behalf of the user using the method [answerWebAppQuery](https://core.telegram.org/bots/api#answerwebappquery). Available only in private chats between a user and the bot. Not supported for messages sent on behalf of a business account." })), "login_url": Schema.optionalKey(Schema.suspend((): Schema.Codec<LoginUrl> => LoginUrl).annotate({ "description": "*Optional*. An HTTPS URL used to automatically authorize the user. Can be used as a replacement for the [Telegram Login Widget](https://core.telegram.org/widgets/login)." })), "switch_inline_query": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. If set, pressing the button will prompt the user to select one of their chats, open that chat and insert the bot's username and the specified inline query in the input field. May be empty, in which case just the bot's username will be inserted. Not supported for messages sent in channel direct messages chats and on behalf of a business account." })), "switch_inline_query_current_chat": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. If set, pressing the button will insert the bot's username and the specified inline query in the current chat's input field. May be empty, in which case only the bot's username will be inserted.  \n  \nThis offers a quick way for the user to open your bot in inline mode in the same chat - good for selecting something from multiple options. Not supported in channels and for messages sent in channel direct messages chats and on behalf of a business account." })), "switch_inline_query_chosen_chat": Schema.optionalKey(Schema.suspend((): Schema.Codec<SwitchInlineQueryChosenChat> => SwitchInlineQueryChosenChat).annotate({ "description": "*Optional*. If set, pressing the button will prompt the user to select one of their chats of the specified type, open that chat and insert the bot's username and the specified inline query in the input field. Not supported for messages sent in channel direct messages chats and on behalf of a business account." })), "copy_text": Schema.optionalKey(Schema.suspend((): Schema.Codec<CopyTextButton> => CopyTextButton).annotate({ "description": "*Optional*. Description of the button that copies the specified text to the clipboard" })), "callback_game": Schema.optionalKey(Schema.suspend((): Schema.Codec<CallbackGame> => CallbackGame).annotate({ "description": "*Optional*. Description of the game that will be launched when the user presses the button.  \n  \n**NOTE:** This type of button **must** always be the first button in the first row." })), "pay": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Specify *True*, to send a [Pay button](https://core.telegram.org/bots/api#payments). Substrings “![⭐](https://telegram.org/img/emoji/40/E2AD90.png)” and “XTR” in the buttons's text will be replaced with a Telegram Star icon.  \n  \n**NOTE:** This type of button **must** always be the first button in the first row and can only be used in invoice messages." })) }).annotate({ "description": "This object represents one button of an inline keyboard. Exactly one of the fields other than *text*, *icon\\_custom\\_emoji\\_id*, and *style* must be used to specify the type of the button.", "identifier": "InlineKeyboardButton" })
export type InputRichMessageContent = { readonly "rich_message": InputRichMessage }
