export type Invoice = { readonly "title": string, readonly "description": string, readonly "start_parameter": string, readonly "currency": Currencies, readonly "total_amount": number }
export const Invoice = Schema.Struct({ "title": Schema.String.annotate({ "description": "Product name" }), "description": Schema.String.annotate({ "description": "Product description" }), "start_parameter": Schema.String.annotate({ "description": "Unique bot deep-linking parameter that can be used to generate this invoice" }), "currency": Schema.suspend((): Schema.Codec<Currencies> => Currencies).annotate({ "description": "Three-letter ISO 4217 [currency](https://core.telegram.org/bots/payments#supported-currencies) code, or “XTR” for payments in [Telegram Stars](https://t.me/BotNews/90)" }), "total_amount": Schema.Number.annotate({ "description": "Total price in the *smallest units* of the currency (integer, **not** float/double). For example, for a price of `US$ 1.45` pass `amount = 145`. See the *exp* parameter in [currencies.json](https://core.telegram.org/bots/payments/currencies.json), it shows the number of digits past the decimal point for each currency (2 for the majority of currencies)." }).check(Schema.isInt().annotate({ "expected": "an integer" })) }).annotate({ "description": "This object contains basic information about an invoice.", "identifier": "Invoice" })
