export const RefundedPayment = Schema.Struct({ "currency": Schema.suspend((): Schema.Codec<Currencies> => Currencies).annotate({ "description": "Three-letter ISO 4217 [currency](https://core.telegram.org/bots/payments#supported-currencies) code, or “XTR” for payments in [Telegram Stars](https://t.me/BotNews/90). Currently, always “XTR”." }), "total_amount": Schema.Number.annotate({ "description": "Total refunded price in the *smallest units* of the currency (integer, **not** float/double). For example, for a price of `US$ 1.45`, `total_amount = 145`. See the *exp* parameter in [currencies.json](https://core.telegram.org/bots/payments/currencies.json), it shows the number of digits past the decimal point for each currency (2 for the majority of currencies)." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "invoice_payload": Schema.String.annotate({ "description": "Bot-specified invoice payload" }), "telegram_payment_charge_id": Schema.String.annotate({ "description": "Telegram payment identifier" }), "provider_payment_charge_id": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Provider payment identifier" })) }).annotate({ "description": "This object contains basic information about a refunded payment.", "identifier": "RefundedPayment" })
export type InputInvoiceMessageContent = { readonly "title": string, readonly "description": string, readonly "payload": string, readonly "provider_token"?: string, readonly "currency": Currencies, readonly "prices": ReadonlyArray<LabeledPrice>, readonly "max_tip_amount"?: number, readonly "suggested_tip_amounts"?: ReadonlyArray<number>, readonly "provider_data"?: string, readonly "photo_url"?: string, readonly "photo_size"?: number, readonly "photo_width"?: number, readonly "photo_height"?: number, readonly "need_name"?: boolean, readonly "need_phone_number"?: boolean, readonly "need_email"?: boolean, readonly "need_shipping_address"?: boolean, readonly "send_phone_number_to_provider"?: boolean, readonly "send_email_to_provider"?: boolean, readonly "is_flexible"?: boolean }
export const InputInvoiceMessageContent = Schema.Struct({ "title": Schema.String.annotate({ "description": "Product name, 1-32 characters" }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(Schema.isMaxCodePoints(32).annotate({ "expected": "a string with at most 32 code points" })), "description": Schema.String.annotate({ "description": "Product description, 1-255 characters" }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(Schema.isMaxCodePoints(255).annotate({ "expected": "a string with at most 255 code points" })), "payload": Schema.String.annotate({ "description": "Bot-defined invoice payload, 1-128 bytes. This will not be displayed to the user, use it for your internal processes." }), "provider_token": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Payment provider token, obtained via [@BotFather](https://t.me/botfather). Pass an empty string for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "currency": Schema.suspend((): Schema.Codec<Currencies> => Currencies).annotate({ "description": "Three-letter ISO 4217 currency code, see [more on currencies](https://core.telegram.org/bots/payments#supported-currencies). Pass “XTR” for payments in [Telegram Stars](https://t.me/BotNews/90)." }), "prices": Schema.Array(LabeledPrice).annotate({ "description": "Price breakdown, a JSON-serialized list of components (e.g. product price, tax, discount, delivery cost, delivery tax, bonus, etc.). Must contain exactly one item for payments in [Telegram Stars](https://t.me/BotNews/90)." }), "max_tip_amount": Schema.optionalKey(Schema.Number.annotate({ "description": "*Optional*. The maximum accepted amount for tips in the *smallest units* of the currency (integer, **not** float/double). For example, for a maximum tip of `US$ 1.45` pass `max_tip_amount = 145`. See the *exp* parameter in [currencies.json](https://core.telegram.org/bots/payments/currencies.json), it shows the number of digits past the decimal point for each currency (2 for the majority of currencies). Defaults to 0. Not supported for payments in [Telegram Stars](https://t.me/BotNews/90).", "default": 0 }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "suggested_tip_amounts": Schema.optionalKey(Schema.Array(Schema.Int).annotate({ "description": "*Optional*. A JSON-serialized array of suggested amounts of tip in the *smallest units* of the currency (integer, **not** float/double). At most 4 suggested tip amounts can be specified. The suggested tip amounts must be positive, passed in a strictly increased order and must not exceed *max\\_tip\\_amount*." })), "provider_data": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. A JSON-serialized object for data about the invoice, which will be shared with the payment provider. A detailed description of the required fields should be provided by the payment provider." })), "photo_url": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. URL of the product photo for the invoice. Can be a photo of the goods or a marketing image for a service." })), "photo_size": Schema.optionalKey(Schema.Number.annotate({ "description": "*Optional*. Photo size in bytes" }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "photo_width": Schema.optionalKey(Schema.Number.annotate({ "description": "*Optional*. Photo width" }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "photo_height": Schema.optionalKey(Schema.Number.annotate({ "description": "*Optional*. Photo height" }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "need_name": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if you require the user's full name to complete the order. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "need_phone_number": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if you require the user's phone number to complete the order. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "need_email": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if you require the user's email address to complete the order. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "need_shipping_address": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if you require the user's shipping address to complete the order. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "send_phone_number_to_provider": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if the user's phone number should be sent to the provider. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "send_email_to_provider": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if the user's email address should be sent to the provider. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })), "is_flexible": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* if the final price depends on the shipping method. Ignored for payments in [Telegram Stars](https://t.me/BotNews/90)." })) }).annotate({ "description": "Represents the [content](https://core.telegram.org/bots/api#inputmessagecontent) of an invoice message to be sent as the result of an inline query.", "identifier": "InputInvoiceMessageContent" })
