export type SuggestedPostParameters = { readonly "price"?: SuggestedPostPrice, readonly "send_date"?: number }
export const SuggestedPostParameters = Schema.Struct({ "price": Schema.optionalKey(Schema.suspend((): Schema.Codec<SuggestedPostPrice> => SuggestedPostPrice).annotate({ "description": "*Optional*. Proposed price for the post. If the field is omitted, then the post is unpaid." })), "send_date": Schema.optionalKey(Schema.Number.annotate({ "description": "*Optional*. Proposed send date of the post. If specified, then the date must be between 300 second and 2678400 seconds (30 days) in the future. If the field is omitted, then the post can be published at any time within 30 days at the sole discretion of the user who approves it." }).check(Schema.isInt().annotate({ "expected": "an integer" }))) }).annotate({ "description": "Contains parameters of a post that is being suggested by the bot.", "identifier": "SuggestedPostParameters" })
