export type KeyboardButtonRequestChat = { readonly "request_id": number, readonly "chat_is_channel": boolean, readonly "chat_is_forum"?: boolean, readonly "chat_has_username"?: boolean, readonly "chat_is_created"?: boolean, readonly "user_administrator_rights"?: ChatAdministratorRights, readonly "bot_administrator_rights"?: ChatAdministratorRights, readonly "bot_is_member"?: boolean, readonly "request_title"?: boolean, readonly "request_username"?: boolean, readonly "request_photo"?: boolean }
export const KeyboardButtonRequestChat = Schema.Struct({ "request_id": Schema.Number.annotate({ "description": "Signed 32-bit identifier of the request, which will be received back in the [ChatShared](https://core.telegram.org/bots/api#chatshared) object. Must be unique within the message." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "chat_is_channel": Schema.Boolean.annotate({ "description": "Pass *True* to request a channel chat, pass *False* to request a group or a supergroup chat" }), "chat_is_forum": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request a forum supergroup, pass *False* to request a non-forum chat. If not specified, no additional restrictions are applied." })), "chat_has_username": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request a supergroup or a channel with a username, pass *False* to request a chat without a username. If not specified, no additional restrictions are applied." })), "chat_is_created": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request a chat owned by the user. Otherwise, no additional restrictions are applied." })), "user_administrator_rights": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatAdministratorRights> => ChatAdministratorRights).annotate({ "description": "*Optional*. A JSON-serialized object listing the required administrator rights of the user in the chat. The rights must be a superset of *bot\\_administrator\\_rights*. If not specified, no additional restrictions are applied." })), "bot_administrator_rights": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatAdministratorRights> => ChatAdministratorRights).annotate({ "description": "*Optional*. A JSON-serialized object listing the required administrator rights of the bot in the chat. The rights must be a subset of *user\\_administrator\\_rights*. If not specified, no additional restrictions are applied." })), "bot_is_member": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request a chat with the bot as a member. Otherwise, no additional restrictions are applied." })), "request_title": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request the chat's title" })), "request_username": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request the chat's username" })), "request_photo": Schema.optionalKey(Schema.Boolean.annotate({ "description": "*Optional*. Pass *True* to request the chat's photo" })) }).annotate({ "description": "This object defines the criteria used to request a suitable chat. Information about the selected chat will be shared with the bot when the corresponding button is pressed. The bot will be granted requested rights in the chat if appropriate. [More about requesting chats »](https://core.telegram.org/bots/features#chat-and-user-selection).", "identifier": "KeyboardButtonRequestChat" })
export type BotCommandScope = BotCommandScopeDefault | BotCommandScopeAllPrivateChats | BotCommandScopeAllGroupChats | BotCommandScopeAllChatAdministrators | BotCommandScopeChat | BotCommandScopeChatAdministrators | BotCommandScopeChatMember
export const BotCommandScope = Schema.Union([BotCommandScopeDefault, BotCommandScopeAllPrivateChats, BotCommandScopeAllGroupChats, BotCommandScopeAllChatAdministrators, BotCommandScopeChat, BotCommandScopeChatAdministrators, BotCommandScopeChatMember], { mode: "oneOf" }).annotate({ "description": "This object represents the scope to which bot commands are applied. Currently, the following 7 scopes are supported:\n\n*   [BotCommandScopeDefault](https://core.telegram.org/bots/api#botcommandscopedefault)\n*   [BotCommandScopeAllPrivateChats](https://core.telegram.org/bots/api#botcommandscopeallprivatechats)\n*   [BotCommandScopeAllGroupChats](https://core.telegram.org/bots/api#botcommandscopeallgroupchats)\n*   [BotCommandScopeAllChatAdministrators](https://core.telegram.org/bots/api#botcommandscopeallchatadministrators)\n*   [BotCommandScopeChat](https://core.telegram.org/bots/api#botcommandscopechat)\n*   [BotCommandScopeChatAdministrators](https://core.telegram.org/bots/api#botcommandscopechatadministrators)\n*   [BotCommandScopeChatMember](https://core.telegram.org/bots/api#botcommandscopechatmember)", "identifier": "BotCommandScope" })
