export const MessageOriginChat = Schema.Struct({ "type": Schema.Literal("chat").annotate({ "description": "Type of the message origin, always “chat”" }), "date": Schema.Number.annotate({ "description": "Date the message was sent originally in Unix time" }).check(Schema.isInt().annotate({ "expected": "an integer" })), "sender_chat": Schema.suspend((): Schema.Codec<Chat> => Chat).annotate({ "description": "Chat that sent the message originally" }), "author_signature": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. For messages originally sent by an anonymous chat administrator, original message author signature" })) }).annotate({ "description": "The message was originally sent on behalf of a chat to a group chat.", "identifier": "MessageOriginChat" })
