export const MessageOriginChannel = Schema.Struct({ "type": Schema.Literal("channel").annotate({ "description": "Type of the message origin, always “channel”" }), "date": Schema.Number.annotate({ "description": "Date the message was sent originally in Unix time" }).check(Schema.isInt().annotate({ "expected": "an integer" })), "chat": Schema.suspend((): Schema.Codec<Chat> => Chat).annotate({ "description": "Channel chat to which the message was originally sent" }), "message_id": Schema.Number.annotate({ "description": "Unique message identifier inside the chat" }).check(Schema.isInt().annotate({ "expected": "an integer" })), "author_signature": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Signature of the original post author" })) }).annotate({ "description": "The message was originally sent to a channel chat.", "identifier": "MessageOriginChannel" })
