export const CallbackQuery = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique identifier for this query" }), "from": Schema.suspend((): Schema.Codec<User> => User).annotate({ "description": "Sender" }), "message": Schema.optionalKey(Schema.suspend((): Schema.Codec<MaybeInaccessibleMessage> => MaybeInaccessibleMessage).annotate({ "description": "*Optional*. Message sent by the bot with the callback button that originated the query" })), "inline_message_id": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Identifier of the message sent via the bot in inline mode, that originated the query" })), "chat_instance": Schema.String.annotate({ "description": "Global identifier, uniquely corresponding to the chat to which the message with the callback button was sent. Useful for high scores in [games](https://core.telegram.org/bots/api#games)." }), "data": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Data associated with the callback button. Be aware that the message originated the query can contain no callback buttons with this data." })), "game_short_name": Schema.optionalKey(Schema.String.annotate({ "description": "*Optional*. Short name of a [Game](https://core.telegram.org/bots/api#games) to be returned, serves as the unique identifier for the game" })) }).annotate({ "description": "This object represents an incoming callback query from a callback button in an [inline keyboard](https://core.telegram.org/bots/features#inline-keyboards). If the button that originated the query was attached to a message sent by the bot, the field *message* will be present. If the button was attached to a message sent via the bot (in [inline mode](https://core.telegram.org/bots/api#inline-mode)), the field *inline\\_message\\_id* will be present. Exactly one of the fields *data* or *game\\_short\\_name* will be present.", "identifier": "CallbackQuery" })
