export const Update = Schema.Struct({ "update_id": Schema.Number.annotate({ "description": "The update's unique identifier. Update identifiers start from a certain positive number and increase sequentially. This identifier becomes especially handy if you're using [webhooks](https://core.telegram.org/bots/api#setwebhook), since it allows you to ignore repeated updates or to restore the correct update sequence, should they get out of order. If there are no new updates for at least a week, then identifier of the next update will be chosen randomly instead of sequentially." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "message": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New incoming message of any kind - text, photo, sticker, etc." })), "edited_message": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New version of a message that is known to the bot and was edited. This update may at times be triggered by changes to message fields that are either unavailable or not actively used by your bot." })), "channel_post": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New incoming channel post of any kind - text, photo, sticker, etc." })), "edited_channel_post": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New version of a channel post that is known to the bot and was edited. This update may at times be triggered by changes to message fields that are either unavailable or not actively used by your bot." })), "business_connection": Schema.optionalKey(Schema.suspend((): Schema.Codec<BusinessConnection> => BusinessConnection).annotate({ "description": "*Optional*. The bot was connected to or disconnected from a business account, or a user edited an existing connection with the bot" })), "business_message": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New message from a connected business account" })), "edited_business_message": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New version of a message from a connected business account" })), "deleted_business_messages": Schema.optionalKey(Schema.suspend((): Schema.Codec<BusinessMessagesDeleted> => BusinessMessagesDeleted).annotate({ "description": "*Optional*. Messages were deleted from a connected business account" })), "guest_message": Schema.optionalKey(Schema.suspend((): Schema.Codec<Message> => Message).annotate({ "description": "*Optional*. New guest message. The bot can use the field *Message.guest\\_query\\_id* and the method [answerGuestQuery](https://core.telegram.org/bots/api#answerguestquery) to send a message in response." })), "message_reaction": Schema.optionalKey(Schema.suspend((): Schema.Codec<MessageReactionUpdated> => MessageReactionUpdated).annotate({ "description": "*Optional*. A reaction to a message was changed by a user. The bot must be an administrator in the chat and must explicitly specify `\"message_reaction\"` in the list of *allowed\\_updates* to receive these updates. The update isn't received for reactions set by bots." })), "message_reaction_count": Schema.optionalKey(Schema.suspend((): Schema.Codec<MessageReactionCountUpdated> => MessageReactionCountUpdated).annotate({ "description": "*Optional*. Reactions to a message with anonymous reactions were changed. The bot must be an administrator in the chat and must explicitly specify `\"message_reaction_count\"` in the list of *allowed\\_updates* to receive these updates. The updates are grouped and can be sent with delay up to a few minutes." })), "inline_query": Schema.optionalKey(Schema.suspend((): Schema.Codec<InlineQuery> => InlineQuery).annotate({ "description": "*Optional*. New incoming [inline](https://core.telegram.org/bots/api#inline-mode) query" })), "chosen_inline_result": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChosenInlineResult> => ChosenInlineResult).annotate({ "description": "*Optional*. The result of an [inline](https://core.telegram.org/bots/api#inline-mode) query that was chosen by a user and sent to their chat partner. Please see our documentation on the [feedback collecting](https://core.telegram.org/bots/inline#collecting-feedback) for details on how to enable these updates for your bot." })), "callback_query": Schema.optionalKey(Schema.suspend((): Schema.Codec<CallbackQuery> => CallbackQuery).annotate({ "description": "*Optional*. New incoming callback query" })), "shipping_query": Schema.optionalKey(Schema.suspend((): Schema.Codec<ShippingQuery> => ShippingQuery).annotate({ "description": "*Optional*. New incoming shipping query. Only for invoices with flexible price." })), "pre_checkout_query": Schema.optionalKey(Schema.suspend((): Schema.Codec<PreCheckoutQuery> => PreCheckoutQuery).annotate({ "description": "*Optional*. New incoming pre-checkout query. Contains full information about checkout." })), "purchased_paid_media": Schema.optionalKey(Schema.suspend((): Schema.Codec<PaidMediaPurchased> => PaidMediaPurchased).annotate({ "description": "*Optional*. A user purchased paid media with a non-empty payload sent by the bot in a non-channel chat" })), "poll": Schema.optionalKey(Schema.suspend((): Schema.Codec<Poll> => Poll).annotate({ "description": "*Optional*. New poll state. Bots receive only updates about manually stopped polls and polls, which are sent by the bot." })), "poll_answer": Schema.optionalKey(Schema.suspend((): Schema.Codec<PollAnswer> => PollAnswer).annotate({ "description": "*Optional*. A user changed their answer in a non-anonymous poll. Bots receive new votes only in polls that were sent by the bot itself." })), "my_chat_member": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatMemberUpdated> => ChatMemberUpdated).annotate({ "description": "*Optional*. The bot's chat member status was updated in a chat. For private chats, this update is received only when the bot is blocked or unblocked by the user." })), "chat_member": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatMemberUpdated> => ChatMemberUpdated).annotate({ "description": "*Optional*. A chat member's status was updated in a chat. The bot must be an administrator in the chat and must explicitly specify `\"chat_member\"` in the list of *allowed\\_updates* to receive these updates." })), "chat_join_request": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatJoinRequest> => ChatJoinRequest).annotate({ "description": "*Optional*. A request to join the chat has been sent. The bot must have the *can\\_invite\\_users* administrator right in the chat to receive these updates." })), "chat_boost": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatBoostUpdated> => ChatBoostUpdated).annotate({ "description": "*Optional*. A chat boost was added or changed. The bot must be an administrator in the chat to receive these updates." })), "removed_chat_boost": Schema.optionalKey(Schema.suspend((): Schema.Codec<ChatBoostRemoved> => ChatBoostRemoved).annotate({ "description": "*Optional*. A boost was removed from a chat. The bot must be an administrator in the chat to receive these updates." })), "managed_bot": Schema.optionalKey(Schema.suspend((): Schema.Codec<ManagedBotUpdated> => ManagedBotUpdated).annotate({ "description": "*Optional*. A new bot was created to be managed by the bot, or token or owner of a managed bot was changed" })) }).annotate({ "description": "This [object](https://core.telegram.org/bots/api#available-types) represents an incoming update.  \nAt most **one** of the optional fields can be present in any given update.", "identifier": "Update" })
